#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Build TTW's bilingual, dependency-free static site. Run from any directory."""
import json, html, hashlib
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent.parent
DATA=json.loads((ROOT/'content/site.json').read_text())
LANG='en'; ROUTE=''; pages=[]; written=set()
def t(en,zh=None):
    if isinstance(en,list): return en[LANG=='zh']
    return zh if LANG=='zh' and zh is not None else en
def esc(value): return html.escape(str(value),quote=True)
def url(route='index.html',lang=None): return ('/zh/' if (lang or LANG)=='zh' else '/')+route
def link(route,label,cls='',**attrs):
    extra=' '.join(f'{k.replace("_","-")}="{esc(v)}"' for k,v in attrs.items())
    return f'<a href="{esc(url(route))}" class="{cls}" {extra}>{label}</a>'
def button(label=None,route='book-a-trial.html',cls='primary'):
    return link(route,label or t('Book a Trial Class','预约体验课'),'button '+cls)
def eye(en,zh):return f'<p class="eyebrow">{t(en,zh)}</p>'
def section(body,cls=''):return f'<section class="section {cls}"><div class="wrap">{body}</div></section>'
def icon(kind):
    shapes={
    'robot':'<path d="M65 38V24m70 14V24"/><circle cx="65" cy="20" r="5" fill="#faac45"/><circle cx="135" cy="20" r="5" fill="#faac45"/><rect x="43" y="39" width="114" height="77" rx="18" fill="#bfe6f1"/><rect x="59" y="54" width="82" height="46" rx="12" fill="#fff"/><circle cx="82" cy="75" r="5" fill="#152f3b"/><circle cx="118" cy="75" r="5" fill="#152f3b"/><path d="M90 88q10 9 20 0M31 67v25m138-25v25M67 117v15m66-15v15"/><rect x="48" y="130" width="35" height="13" rx="4" fill="#faac45"/><rect x="117" y="130" width="35" height="13" rx="4" fill="#faac45"/>',
    'code':'<rect x="24" y="29" width="152" height="103" rx="12" fill="#fff"/><path d="M24 49h152"/><circle cx="38" cy="40" r="2"/><circle cx="48" cy="40" r="2"/><path d="m73 69-20 20 20 20m54-40 20 20-20 20m-16-47-19 56" stroke="#187a5a"/><path d="M58 143h84"/>',
    'circuit':'<rect x="64" y="48" width="72" height="65" rx="7" fill="#faac45"/><path d="M78 34v14m22-14v14m22-14v14M78 113v16m22-16v16m22-16v16M64 65H34V35m30 62H27v34m109-66h35V35m-35 62h36v34"/><rect x="83" y="65" width="34" height="31" rx="3" fill="#fff"/><circle cx="34" cy="29" r="6" fill="#fff"/><circle cx="171" cy="29" r="6" fill="#fff"/><circle cx="27" cy="136" r="6" fill="#fff"/><circle cx="172" cy="136" r="6" fill="#fff"/>',
    'cube':'<path d="m100 19 64 36v69l-64 36-64-36V55Z" fill="#e1d8f7"/><path d="m36 55 64 37 64-37M100 92v68M67 38l65 36v67"/><path d="M18 38v99m-5-94 5-5 5 5m-10 89 5 5 5-5" stroke="#8a76b5"/>',
    'gear':'<path d="M33 115 73 44l74 12 25 65-76 28Z" fill="#d2e8df"/><circle cx="94" cy="86" r="30" fill="#fff"/><circle cx="94" cy="86" r="12" fill="#faac45"/><path d="M94 45v11m0 60v11m-41-41h11m60 0h11M65 57l8 8m42 42 8 8m0-58-8 8m-42 42-8 8"/><circle cx="33" cy="115" r="8" fill="#faac45"/><circle cx="147" cy="56" r="8" fill="#bfe6f1"/>',
    'signpost':'<ellipse cx="99" cy="152" rx="24" ry="7" fill="#ede4f7"/><rect x="93" y="45" width="10" height="107" rx="4" fill="#8a76b5"/><path d="M99 56h54l17 16-17 16H99Z" fill="#faac45"/><path d="M99 96H44l-17 16 17 16h55Z" fill="#bfe6f1"/><circle cx="99" cy="72" r="6" fill="#fff"/><circle cx="99" cy="112" r="6" fill="#fff"/>',
    'exam':'<rect x="50" y="20" width="100" height="135" rx="10" fill="#dceaf5"/><rect x="66" y="42" width="68" height="8" rx="4" fill="#fff"/><rect x="66" y="62" width="68" height="8" rx="4" fill="#fff"/><rect x="66" y="82" width="44" height="8" rx="4" fill="#fff"/><circle cx="138" cy="120" r="28" fill="#faac45"/><path d="m125 120 9 9 18-19" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>',
    'compass':'<circle cx="100" cy="87" r="58" fill="#e5f0e9"/><circle cx="100" cy="87" r="42" fill="#fff"/><path d="M100 32v20m0 70v20m-58-58h20m70 0h20"/><path d="m100 58 16 29-16 29-16-29Z" fill="#bfe6f1"/><circle cx="100" cy="87" r="8" fill="#faac45"/>',
    'medal':'<path d="M76 26h48l22 40-46 22-46-22Z" fill="#fde3c0"/><circle cx="100" cy="110" r="38" fill="#fff"/><path d="m100 88 8 16 18 3-13 12 3 18-16-9-16 9 3-18-13-12 18-3Z" fill="#faac45"/>',
    'shirt':'<path d="M72 32 46 52l13 23 19-13v84h80V62l19 13 13-23-26-20-19 13H91Z" fill="#e1d8f7"/><rect x="80" y="70" width="40" height="30" rx="5" fill="#fff"/><path d="M88 78h24m-24 8h24m-18 8h12"/>',
    'sticker':'<circle cx="100" cy="100" r="46" fill="#fde3c0"/><path d="M100 40v16m0 88v16m-60-60h16m88 0h16M58 58l11 11m62 62 11 11M142 58l-11 11M69 131l-11 11"/><circle cx="100" cy="100" r="20" fill="#faac45"/>',
    'speech':'<path d="M35 45h130a12 12 0 0 1 12 12v55a12 12 0 0 1-12 12H95l-30 25v-25H35a12 12 0 0 1-12-12V57a12 12 0 0 1 12-12Z" fill="#dceaf5"/><path d="M55 75h90M55 95h60"/>',
    'arm':'<rect x="42" y="132" width="116" height="22" rx="6" fill="#e1d8f7"/><circle cx="100" cy="122" r="12" fill="#fff"/><path d="M100 122 66 76"/><circle cx="66" cy="76" r="10" fill="#fff"/><path d="M66 76 133 48"/><circle cx="133" cy="48" r="8" fill="#faac45"/><path d="M133 48 118 27M133 48 150 33"/>'}
    return f'<svg viewBox="0 0 200 175" fill="none" stroke="#244956" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{shapes[kind]}</svg>'
def program_cards(items=None):
    rows=items or DATA['programs']
    out=[]
    for p in rows:
        out.append(f'''<article class="card program-card {p['color']}"><div class="card-visual">{icon(p['icon'])}</div><p class="meta">{t(p['grade'])}</p><h3>{link('programs/'+p['slug']+'.html',t(p['name']),'title')}</h3><span class="status">{t(p['status'])}</span><p>{t(p['description'])}</p>{link('programs/'+p['slug']+'.html',t('Explore this program →','了解此课程 →'),'text-link')}</article>''')
    if len(rows)==len(DATA['programs']):
        out.append(f'''<article class="card program-card"><div class="card-visual">{icon('signpost')}</div><p class="meta">{t('Your learner. Their starting point.','从学习者自身出发。')}</p><h3>{t('A little help choosing?','需要选课建议？')}</h3><p>{t('You don’t need to know the technology to take the first step. Tell us what your learner enjoys, and we can explore the options together.','迈出第一步，不需要先懂所有技术。告诉我们孩子喜欢什么，一起探索合适的方向。')}</p>{link('book-a-trial.html?program=not-sure',t('Find a starting point →','寻找学习起点 →'),'text-link')}</article>''')
    return '<div class="grid program-grid">'+''.join(out)+'</div>'
def age_cards():
    return '<div class="grid four">'+''.join(f'''<a class="card age-card" href="{url('age-groups/'+a['slug']+'.html')}"><span class="age-number">0{i+1}</span><h3>{t(a['name'])}</h3><p>{t(a['verb'])}</p><span class="small">{t(a['status'])}</span><span class="arrow" aria-hidden="true">↗</span></a>''' for i,a in enumerate(DATA['ages']))+'</div>'
def cta():return section(f'''<div class="banner"><div>{eye('A good place to begin','从这里开始')}<h2>{t('A little curiosity.<br>A world of possibilities.','一点好奇心，<br>开启无限可能。')}</h2><p>{t('Tell us about your learner. We’ll help you explore a suitable starting point and confirm trial availability.','告诉我们孩子的兴趣与经验，一起寻找合适起点，并确认体验课安排。')}</p></div>{button()}</div>''')
FAQ=[
['Does my child need experience?','孩子需要有基础吗？','No prior robotics experience is needed to ask about the Grades 3–6 starting pathway. For older learners, share their interests and experience so TTW can discuss a suitable entry point.','咨询 3–6 年级入门方向不需要机器人基础。对于高年级学生，请提供兴趣与经验，以便沟通合适的学习起点。'],
['Which program should we choose?','应该选择哪门课程？','Start with the learner’s grade and what they enjoy making. LEGO Robotics connects building and block coding; 3D design and, for high schoolers, the Distilled series can extend those interests as these pathways become available.','可从学生的年级和创作兴趣出发。LEGO 机器人结合搭建与图形化编程；3D 设计以及面向高中生的 Distilled 系列可在开放后延伸这些兴趣。'],
['What does a trial request include?','体验申请包含什么？','Share a grade group, program interest and preferred timing. TTW will discuss the activity, location, duration and any fee before confirming a place. An inquiry does not reserve a seat.','提供年级、课程兴趣和希望的时间。TTW 将在确认席位前沟通活动、地点、时长及费用。提交咨询不等于预留席位。'],
['What are the fees and class times?','费用和上课时间是什么？','Schedules, session counts, fees, tax treatment and equipment inclusions are not yet published. Ask for the current details in writing before deciding to enroll.','排期、课次、费用、税费及设备是否包含尚未公布。请在决定报名前索取当前书面信息。'],
['Can we learn without joining a competition?','不参加比赛也可以学习吗？','Yes. The learning approach values building, testing and explaining a project in its own right. Competition is an optional direction, subject to a suitable group and current eligibility.','可以。学习方向重视搭建、测试和解释项目本身。竞赛属于可选路径，需结合合适的班组与当季参赛资格。'],
['Are all listed programs running now?','网站上所有课程都已开班吗？','No. Core robotics pathways are the initial focus. Advanced CAD, the Distilled series, high school pathways and adult workshops include future offerings. Each page identifies its status; confirm availability with TTW.','并非所有课程都已开班。初期重点是核心机器人路径；进阶 CAD、Distilled 系列、高中及成人工作坊包含未来计划。各页面会标明状态，请向 TTW 确认可用课程。'],
['Where will classes take place?','课程在哪里上？','TTW is located at 15A, 20 Crown Steel Drive, Markham, ON L3R 9X8. Confirm parking and arrival instructions with TTW before your visit.','TTW 地址为 15A, 20 Crown Steel Drive, Markham, ON L3R 9X8。到访前请向 TTW 确认停车及到达指引。'],
['What about supervision, pickup and missed classes?','安全指导、接送和缺课如何安排？','Before enrollment, request the class supervision arrangements, authorized-pickup procedure, equipment guidance, and written refund and makeup terms. These details will depend on the confirmed offering.','报名前，请索取课堂指导安排、授权接送流程、设备使用指导，以及退款和补课的书面条款。具体安排取决于最终确认的课程。']]
def faqs(all=False):return '<div class="faq">'+''.join(f'<details><summary>{t(x[0],x[1])}</summary><p>{t(x[2],x[3])}</p></details>' for x in (FAQ if all else FAQ[:4]))+'</div>'
def heading(title,desc,kicker=None):return f'<div class="wrap"><div class="page-hero">{eye(*(kicker or ["Build skills. Make discoveries.","积累技能，探索新知。"]))}<h1>{title}</h1><p class="lead">{desc}</p></div></div>'
def render(route,title,desc,body,nav='',noindex=False):
    global ROUTE
    ROUTE=route
    navs=[('programs/index.html',t('Programs','课程'),'programs'),('age-groups/index.html',t('Age Groups','年龄分组'),'ages'),('first-lego-league.html','FIRST LEGO League','fll'),('programs/wro.html','WRO','wro'),('camps.html',t('Camps','营地'),'camps'),('about.html',t('About','关于'),'about')]
    navigation=''.join(link(r,l,aria_current='page') if n==nav else link(r,l) for r,l,n in navs)
    canonical=DATA['url']+url(route)
    og=DATA['url']+'/image/Makerspace.png'
    schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':canonical,'inLanguage':t('en-CA','zh-Hans'),'isPartOf':{'@type':'WebSite','name':DATA['name'],'url':DATA['url']}}
    if route=='index.html': schema={'@context':'https://schema.org','@type':'EducationalOrganization','name':DATA['name'],'url':DATA['url'],'logo':DATA['url']+'/image/logo.png','email':DATA['email'],'address':{'@type':'PostalAddress','streetAddress':'15A, 20 Crown Steel Drive','addressLocality':'Markham','addressRegion':'ON','postalCode':'L3R 9X8','addressCountry':'CA'},'areaServed':{'@type':'City','name':'Markham'}}
    prefix=t('en','zh-Hans')
    csshash=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:10]
    jshash=hashlib.sha256((ROOT/'assets/site.js').read_bytes()).hexdigest()[:10]
    content=f'''<!doctype html>
<html lang="{prefix}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Tinker Tech World</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#152f3b"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en-CA" href="{DATA['url']+url(route,'en')}"><link rel="alternate" hreflang="zh-Hans" href="{DATA['url']+url(route,'zh')}"><link rel="alternate" hreflang="x-default" href="{DATA['url']+url(route,'en')}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title)} | Tinker Tech World"><meta property="og:description" content="{esc(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{og}"><meta property="og:image:alt" content="{t('TTW makerspace concept illustration','TTW 创客空间概念示意图')}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/webp" href="/assets/logo.webp"><link rel="stylesheet" href="/assets/site.css?v={csshash}"><script src="/assets/site.js?v={jshash}" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body data-language="{LANG}"><a class="skip" href="#main">{t('Skip to content','跳到正文')}</a><div class="topbar"><div class="wrap"><span>{t('Curious minds. Real-world skills. · Markham, Ontario','保持好奇，掌握真实技能。· 安大略省万锦市')}</span><span>{link('contact.html',t('Talk to TTW','联系 TTW'))}</span><a class="language-link" href="{url(route,'zh' if LANG=='en' else 'en')}" lang="{'zh-Hans' if LANG=='en' else 'en'}" hreflang="{'zh-Hans' if LANG=='en' else 'en-CA'}">{t('中文','English')}</a></div></div>
<header class="site-header"><div class="wrap header-row"><a class="brand" href="{url()}" aria-label="Tinker Tech World"><img src="/assets/logo.webp" width="90" height="75" alt="Tinker Tech World"><span class="brand-tagline">{t('Building skills for a changing world','为不断变化的世界培养技能')}</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">{t('Menu','菜单')} <span aria-hidden="true">☰</span></button><nav class="nav" id="navigation" aria-label="{t('Main navigation','主导航')}">{navigation}</nav><div class="header-trial">{button(t('Book a Trial ↗','预约体验 ↗'))}</div></div></header>
<main id="main" tabindex="-1">{'' if route=='index.html' else '<nav class="wrap breadcrumbs" aria-label="'+t('Breadcrumb','面包屑导航')+'">'+link('index.html',t('Home','首页'))+' / <span>'+esc(title)+'</span></nav>'}{body}</main>
<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="{url()}" aria-label="Tinker Tech World"><img src="/assets/logo.webp" width="90" height="75" loading="lazy" alt="Tinker Tech World"></a><p>{t('A place for curious minds<br>and capable makers.','让好奇的头脑，<br>成长为有能力的创客。')}</p><p>{t(DATA['location'])}</p></div><div><h3>{t('Explore','探索')}</h3>{link('programs/index.html',t('All Programs','全部课程'))}{link('age-groups/index.html',t('Find Your Age Group','按年龄选课'))}{link('first-lego-league.html','FIRST LEGO League')}{link('programs/wro.html','World Robot Olympiad')}{link('camps.html',t('Camps','营地'))}{link('project-gallery.html',t('Project Gallery','项目展示'))}</div><div><h3>{t('Get to know TTW','了解 TTW')}</h3>{link('about.html',t('About TTW','关于 TTW'))}{link('makerspace.html',t('Our Learning Approach','学习方式'))}{link('faq.html',t('Parent FAQ','家长常见问题'))}{link('contact.html',t('Contact TTW','联系 TTW'))}{link('privacy.html',t('Privacy','隐私说明'))}</div><div><h3>{t('Start a conversation','开启对话')}</h3><a href="mailto:{DATA['email']}">{DATA['email']}</a><p>{t('Ask about availability, a trial or the right starting point.','咨询开班、体验课或合适的学习起点。')}</p>{link('book-a-trial.html',t('Book a Trial Class →','预约体验课 →'))}{link('join.html',t('Join a Program →','加入课程 →'))}</div></div><div class="footer-bottom"><span>© 2026 Tinker Tech World</span><span>{t('Imagine · Build · Test · Improve','构思 · 搭建 · 测试 · 改进')}</span></div></div></footer>
{'' if route in ['book-a-trial.html','join.html'] else '<aside class="mobile-cta" aria-label="'+t('Trial class','体验课')+'"><span>'+t('Find their starting point.','找到适合孩子的起点。')+'</span>'+button()+'</aside>'}</body></html>'''
    dest=ROOT/(('zh/' if LANG=='zh' else '')+route);dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(content)
    written.add(dest)
    if not noindex:pages.append(canonical)

def home():
    body=f'''<section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy">{eye('Hands-on STEM learning in Markham','万锦市 · 动手实践 STEM 学习')}<h1>{t('Little sparks.<br><em>Big discoveries.</em>','小小灵感，<br><em>大大发现。</em>')}</h1><p class="lead">{t('For the child who asks “how does it work?”<br>Turn that curiosity into confidence through robotics, coding and hands-on engineering.','为每一个爱问“它是怎么工作的？”的孩子，<br>通过机器人、编程和工程实践，将好奇心转化为自信。')}</p><div class="actions">{button(t('Book a Trial Class ↗','预约体验课 ↗'))}{button(t('View Programs','浏览课程'),'programs/index.html','outline')}</div><p class="hero-note">{t('Start with a conversation. Trial times and any fees are confirmed with you before booking.','从沟通开始。预约前，我们会与您确认体验时间及相关费用。')}</p></div><figure class="hero-visual"><img class="hero-photo" src="/assets/makerspace.webp" srcset="/assets/makerspace-small.webp 640w, /assets/makerspace.webp 1200w" sizes="(max-width:760px) 92vw, 50vw" width="1200" height="800" fetchpriority="high" alt="{t('Concept illustration of learners exploring robotics in a makerspace','学生在创客空间探索机器人的概念示意图')}"><div class="photo-label"><b>{t('Less watching. More wondering.','动手尝试，主动探索。')}</b><span>{t('Imagine → Build → Test → Improve','构思 → 搭建 → 测试 → 改进')}</span></div><figcaption>{t('TTW learning-space concept illustration; not a facility photograph.','TTW 学习空间概念示意图，并非实际场地照片。')}</figcaption></figure></div><div class="trust-strip">{''.join('<div class="trust-item"><span class="mark" aria-hidden="true">'+mark+'</span>'+t(en,zh)+'</div>' for mark,en,zh in [('↗','A pathway that grows with them','随孩子成长的学习路径'),('◇','Build, test and explain','搭建、测试、解释'),('◎','Start with their interests','从他们的兴趣出发')])}</div></div></section>'''
    body+=section(f'''<div class="section-head"><div>{eye('Find their starting point','找到适合的起点')}<h2>{t('Big possibilities.<br>The right next step.','广阔可能，<br>从合适的一步开始。')}</h2></div>{link('age-groups/index.html',t('Explore learning pathways →','探索学习路径 →'),'text-link')}</div>{age_cards()}''','tinted')
    body+=section(f'''<div class="section-head"><div>{eye('Explore our programs','探索课程')}<h2>{t('More than a skill.<br>A new way to think.','不止一项技能，<br>更是一种思考方式。')}</h2></div><p class="small">{t('Start with robotics. Discover where it can lead.<br>Availability is shown on every program page.','从机器人出发，探索更多方向。<br>每个课程页面均注明开班状态。')}</p></div>{program_cards()}''')
    body+=section(f'''<div class="split"><div>{eye('The TTW approach','TTW 学习方式')}<h2>{t('The best part?<br>“I figured it out.”','最棒的时刻？<br>“我想明白了！”')}</h2><p class="lead">{t('A working robot is a beginning. Understanding why it works—and knowing what to try when it doesn’t—is where deeper learning happens.','机器人动起来，只是开始。理解它为什么能工作，知道失败时该尝试什么，才是更深入的学习。')}</p>{link('makerspace.html',t('See how learning connects →','了解学习如何连接 →'),'text-link')}</div><div class="process">{process()}</div></div>''','tinted')
    body+=section(f'''<div class="split"><div>{eye('Make progress visible','让进步看得见')}<h2>{t('A project tells<br>a bigger story.','每个项目背后，<br>都有成长故事。')}</h2><p class="lead">{t('Look beyond the finished object. Notice the questions, tests and small improvements that show how a learner’s thinking is growing.','不只看完成的作品，也关注其中的问题、测试和小小改进，理解孩子的思考如何成长。')}</p>{link('project-gallery.html',t('Explore project ideas →','探索项目创意 →'),'text-link')}</div><div class="notebook">{eye('Inside an engineering notebook','工程笔记本里')}<h3>{t('The questions behind the build','作品背后的问题')}</h3><ul><li>{t('What am I trying to make?','我想做出什么？')}</li><li>{t('What happened when I tested it?','测试时发生了什么？')}</li><li>{t('What did I change, and why?','我改了什么，为什么？')}</li><li>{t('How can I show it works better?','如何证明它变得更好了？')}</li></ul><p class="line">{t('A learning approach grounded in the TTW curriculum.','源于 TTW 课程理念的学习方式。')}</p></div></div>''')
    body+=section(f'''<div class="section-head"><div>{eye('For parents','给家长')}<h2>{t('A few good questions.','您可能想了解。')}</h2></div>{link('faq.html',t('All parent questions →','查看全部常见问题 →'),'text-link')}</div>{faqs()}''','tinted')+cta()
    render('index.html',t('Robotics & Hands-on STEM in Markham','万锦机器人与 STEM 实践学习'),t('Explore TTW robotics and STEM learning pathways in Markham. Find a program by grade and request a trial class.','探索 TTW 万锦机器人与 STEM 学习路径。按年级了解课程，申请体验课。'),body)

def program_page(p):
    route='programs/'+p['slug']+'.html'
    wro_link=f'<a class="text-link" href="https://wro-association.org/" target="_blank" rel="noopener">{t("Official WRO Association site ↗","WRO 官方协会网站 ↗")}</a>' if p['slug']=='wro' else ''
    body=f'''<div class="wrap page-hero"><div class="detail-hero"><div>{eye(t(p['name']),t(p['name']))}<h1>{t(p['intro'])}</h1><p class="lead">{t(p['description'])}</p><span class="status">{t(p['status'])}</span><div class="actions">{button(t('Ask about this program ↗','咨询此课程 ↗'),'book-a-trial.html?program='+p['slug'])}{link('programs/index.html',t('All programs','全部课程'),'text-link')}{wro_link}</div></div><div class="detail-art">{icon(p['icon'])}</div></div><dl class="facts"><div><dt>{t('Suggested learners','建议学习阶段')}</dt><dd>{t(p['grade'])}</dd></div><div><dt>{t('Format','学习形式')}</dt><dd>{t('Guided, project-based learning','指导下开展项目学习')}</dd></div><div><dt>{t('Schedule & tuition','排期与学费')}</dt><dd>{t('Confirm with TTW before enrollment','报名前请向 TTW 确认')}</dd></div></dl></div>'''
    body+=section(f'''<div class="split"><div>{eye('What learning looks like','学习内容')}<h2>{t('Skills with a purpose.','让技能发挥作用。')}</h2><ul class="check-list">{''.join('<li>'+t(s)+'</li>' for s in p['skills'])}</ul></div><div class="notebook">{eye('Illustrative project · Not a student result','项目示例 · 非学生实际成果')}<h3>{t(p['project'])}</h3><p>{t(p['challenge'])}</p><p class="line">{t('Activities depend on the learner’s level and confirmed course.','具体活动取决于学生水平和最终确认的课程。')}</p></div></div>''','tinted')
    body+=section(f'''<div class="split"><div><h2>{t('A starting point that fits.','适合自己的学习起点。')}</h2><p class="lead">{t(p['entry'])}</p></div><div><h3>{t('Before you join','报名前请了解')}</h3><p>{t('Ask about session length, number of classes, tuition and taxes, equipment, supervision, and refund or makeup terms. TTW will confirm these details for the available offering.','请咨询每次课时长、课次、学费及税费、设备、指导安排，以及退款或补课条款。TTW 将针对可提供的课程确认具体信息。')}</p>{button(t('Join a Program →','加入课程 →'),'join.html?program='+p['slug'],'outline')}</div></div>''')
    if p['slug']=='wro':
        body+=section(f'''<div class="callout">{t('Categories, age ranges and formats are set by the World Robot Olympiad Association and can change by season. TTW will need to confirm the current format, local eligibility and coaching capacity before offering a team place.','类别、年龄范围和赛制由 World Robot Olympiad Association 制定，并可能随赛季调整。TTW 需确认当前形式、本地参赛资格及教练安排后，才能提供战队席位。')} <a href="https://wro-association.org/">{t('Check the official WRO Association information →','查看 WRO 官方信息 →')}</a></div><p class="small">{t('Official overview checked September 16, 2026. World Robot Olympiad and WRO are trademarks of their respective owner; this page does not claim TTW affiliation, endorsement or team registration.','官方概览核对日期：2026 年 9 月 16 日。World Robot Olympiad 及 WRO 为其权利人的商标；本页不表示 TTW 已获其认可、授权或完成战队注册。')}</p>''')
    body+=section(f'''{eye('Keep exploring','继续探索')}<h2>{t('Where could this lead?','下一步，走向哪里？')}</h2><p class="lead">{t('The learning pathways connect. Explore the next area and discuss readiness and availability with TTW.','各学习方向相互连接。了解下一项技能，并与 TTW 讨论能力要求和开班情况。')}</p>{link('programs/'+p['nextSlug']+'.html',t(p['next'])+' →','text-link')}''','tinted')+cta()
    render(route,t(p['name']),t(p['description']),body,'wro' if p['slug']=='wro' else 'programs')
def age_page(a):
    items=[p for p in DATA['programs'] if p['slug'] in a['programs']]
    body=heading(t(a['name'])+'<br>'+t(a['verb']),t(a['description']),[t(a['status']),t(a['status'])])
    body+=section(f'''<div class="split"><div><h2>{t('The growth to look for.','值得关注的成长。')}</h2><p class="lead">{t(a['focus'])}</p></div><div class="card"><h3>{t('Grade is a guide, not a placement test.','年级是参考，能力才是起点。')}</h3><p>{t('Share interests and prior experience. The right starting point depends on what the learner can already do and explain.','请分享兴趣与过往经验。合适的起点取决于学生已经能做什么、能解释什么。')}</p>{button(t('Discuss a starting point','咨询学习起点'),'book-a-trial.html?grade='+a['slug'])}</div></div>''','tinted')
    body+=section(f'<div class="section-head"><h2>{t("Explore relevant pathways","探索相关学习方向")}</h2></div>'+program_cards(items))+cta()
    render('age-groups/'+a['slug']+'.html',t(a['name']),t(a['description']),body,'ages')
def process():
    return ''.join(f'<div class="process-item"><div><h3>{t(en,zh)}</h3><p>{t(desc,zd)}</p></div></div>' for en,zh,desc,zd in [('Imagine & build','构思与搭建','Start with a question. Make a plan, try an idea and connect it to something tangible.','从问题开始，制定计划，尝试想法，把它变成摸得到的作品。'),('Test & improve','测试与改进','Notice what works, investigate what doesn’t, and make a thoughtful change.','观察成功之处，探究失败原因，并有依据地改进。'),('Explain & connect','解释与连接','Share the reasoning behind the project and carry those skills into the next challenge.','分享项目背后的思考，将技能带入下一个挑战。')])

def booking(join=False):
    title=t('Join a Program','加入课程') if join else t('Book a Trial Class','预约体验课')
    options=lambda rows:'<option value="">'+t('Please select','请选择')+'</option>'+''.join('<option value="'+x['slug']+'">'+t(x['name'])+'</option>' for x in rows)
    field=lambda id,label,kind='text',req=False:f'<div class="field"><label for="{id}">{label}{t(" (required)","（必填）") if req else t(" (optional)","（选填）")}</label><input id="{id}" name="{id}" type="{kind}" maxlength="{100 if id=="name" else 150}" {"required" if req else ""} autocomplete="{id if id in ["name","email"] else "off"}"></div>'
    body=heading(title,t('Let’s find a starting point that feels right. Tell us a little about the learner and the program you’re interested in.','一起寻找合适的学习起点。请介绍学生的情况和感兴趣的课程。'),['Your next step','下一步'])
    body+=section(f'''<div class="form-layout"><div class="form-card"><noscript><div class="callout">{t('The request builder needs JavaScript. Please email your grade group, interests and preferred timing to','申请生成器需要 JavaScript。请将年级、兴趣及希望的时间发送至')} <a href="mailto:{DATA['email']}">{DATA['email']}</a>.</div></noscript><form id="inquiry-form" data-intent="{'join' if join else 'trial'}" data-email="{DATA['email']}" hidden><h2 style="font-size:1.6rem">{t('Tell us about your learner','介绍一下学习者')}</h2><p class="form-help">{t('For a child, please use a parent or guardian’s contact details. No child’s full name is needed.','如果为孩子咨询，请填写家长或监护人的联系方式，无需填写孩子全名。')}</p><div class="field-grid">{field('name',t('Parent / adult learner name','家长 / 成人学习者姓名'),req=True)}{field('email',t('Contact email','联系邮箱'),'email',True)}</div><div class="field-grid"><div class="field"><label for="grade">{t('Grade group (required)','年级分组（必填）')}</label><select name="grade" id="grade" required>{options(DATA['ages'])}</select></div><div class="field"><label for="program">{t('Program interest (required)','课程兴趣（必填）')}</label><select name="program" id="program" required>{options(DATA['programs'])}<option value="fll">FIRST LEGO League</option><option value="camps">{t('Camps','营地')}</option><option value="not-sure">{t('Help me choose','请帮我选课')}</option></select></div></div><div class="field"><label for="timing">{t('Preferred days / times (optional)','希望的日期 / 时间（选填）')}</label><input name="timing" id="timing" maxlength="150" placeholder="{t('e.g. Saturday mornings','例如：周六上午')}"><p class="form-help">{t('A preference, not an available time slot. TTW will confirm availability.','这是时间偏好，并非可预约时段。TTW 将确认具体安排。')}</p></div><div class="field-grid"><div class="field"><label for="area">{t('Postal area (optional)','邮编区域（选填）')}</label><input id="area" name="area" maxlength="3" pattern="[A-Za-z][0-9][A-Za-z]" placeholder="L3R" aria-describedby="area-help"><p class="form-help" id="area-help">{t('First 3 characters only. Helps us understand travel needs.','仅前三位，帮助了解通勤需求。')}</p></div><div class="field"><label for="source">{t('How did you hear about us? (optional)','从哪里了解到我们？（选填）')}</label><select id="source" name="source"><option value="">{t('Please select','请选择')}</option>{''.join(f'<option value="{v}">{t(en,zh)}</option>' for v,en,zh in [('search','Search engine','搜索引擎'),('friend','Friend / family','朋友 / 家人'),('school','School / community','学校 / 社区'),('social','Social media','社交媒体'),('other','Other','其他')])}</select></div></div><div class="field"><label for="notes">{t('Interests, experience or questions (optional)','兴趣、经验或问题（选填）')}</label><textarea id="notes" name="notes" maxlength="700" aria-describedby="notes-help"></textarea><p id="notes-help" class="form-help">{t('Please leave out medical details and other sensitive information.','请勿填写医疗信息或其他敏感资料。')}</p></div><label class="checkbox"><input type="checkbox" name="consent" id="consent" required><span>{t('I am an adult learner or a parent/guardian. I agree to share this inquiry with TTW for a reply.','我是成人学习者或家长 / 监护人，同意向 TTW 分享此咨询，以便获得回复。')} {link('privacy.html',t('Privacy details','隐私说明'))}</span></label><button class="button primary" type="submit">{t('Review my request →','核对我的申请 →')}</button><p class="form-help">{t('Nothing is sent by this button. You’ll review your message, then send it using your email app.','点击此按钮不会发送资料。您将先核对内容，再通过邮件应用发送。')}</p></form><section id="review" class="review" hidden tabindex="-1" aria-labelledby="review-title"><h2 id="review-title" style="font-size:1.5rem">{t('Review, then send','核对后发送')}</h2><p>{t('Your request has not been sent. Open your email app and send the message to TTW. A place is only booked after TTW confirms it with you.','您的申请尚未发送。请打开邮件应用并将信息发送至 TTW。只有收到 TTW 确认后，预约才成立。')}</p><label for="request-preview" class="small">{t('Your message','您的消息')}</label><textarea id="request-preview" readonly></textarea><div class="actions"><a id="send-email" class="button primary" href="mailto:{DATA['email']}">{t('Open email to send ↗','打开邮件发送 ↗')}</a><button type="button" class="button outline" id="copy-request">{t('Copy message','复制消息')}</button></div><a id="download-request" class="text-link" download="TTW-inquiry.txt">{t('Download your request','下载申请内容')}</a><p class="form-help">{t('No email app? Copy the message into your webmail and send it to','没有邮件应用？请将消息复制到网页邮箱并发送至')} <a href="mailto:{DATA['email']}">{DATA['email']}</a>.</p><p id="form-status" class="form-status" role="status"></p></section></div><aside><div class="process">{''.join('<div class="process-item"><div><h3>'+t(e,z)+'</h3><p>'+t(d,zd)+'</p></div></div>' for e,z,d,zd in [('Share an interest','分享兴趣','Tell us what the learner enjoys and what they have tried.','告诉我们学习者喜欢什么、尝试过什么。'),('Discuss the fit','讨论适合的起点','TTW can clarify the starting level, timing, location and any fees.','TTW 将沟通起点、时间、地点和相关费用。'),('Confirm together','共同确认','A trial or enrollment is confirmed directly with TTW. No payment is collected here.','体验课或报名需与 TTW 直接确认。本页面不收取任何费用。')])}</div><div class="callout">{t('Some pathways are still in development. An interest request does not mean a course or team is currently open.','部分方向仍在开发中。登记意向不代表相关课程或战队已经开放。')}</div><h3>{t('Prefer a direct conversation?','想直接联系？')}</h3><a class="text-link" href="mailto:{DATA['email']}">{DATA['email']}</a></aside></div>''')
    render('join.html' if join else 'book-a-trial.html',title,t('Request a TTW trial or program conversation. Review your inquiry and email the team to confirm availability.','申请 TTW 体验课或课程咨询。核对信息并通过邮件联系团队确认安排。'),body)

def other_pages():
    body=heading(t('Find what sparks<br>their curiosity.','找到点燃<br>好奇心的方向。'),t('Connected areas of learning. Start with the core robotics pathway and explore future directions as skills grow.','相互连接的学习领域。从核心机器人路径开始，随着技能成长，探索未来方向。'),['Programs','课程'])
    body+=section(program_cards())+section('<h2>'+t('Not sure where to start?','不确定从哪里开始？')+'</h2><p class="lead">'+t('Grade groups help you explore. Experience and interests help us choose a starting point together.','年级分组帮助探索方向，经验与兴趣帮助我们一起确定起点。')+'</p>'+age_cards(),'tinted')+cta()
    render('programs/index.html',t('Programs','课程'),t('Explore LEGO robotics, 3D design and printing, and the Distilled pathway at TTW.','探索 TTW 的 LEGO 机器人、3D 设计与打印，以及 Distilled 学习路径。'),body,'programs')
    render('age-groups/index.html',t('Age Groups','年龄分组'),t('Find a TTW learning pathway for Grades 3–6, Grades 7–9, high school or adults.','了解适合 3–6 年级、7–9 年级、高中及成人的 TTW 学习路径。'),heading(t('Room to grow.<br>At every stage.','每个阶段，<br>都有成长空间。'),t('A clear starting point today, with a view of what could come next. Read each pathway’s availability before making plans.','了解今天的起点，也看见未来的方向。做计划前，请阅读各路径的开放情况。'))+section(age_cards(),'tinted')+cta(),'ages')
    fll=heading('FIRST LEGO League',t('A team challenge that brings building, coding and problem solving together. Ask TTW about readiness and potential team opportunities.','将搭建、编程和解决问题结合在一起的团队挑战。欢迎向 TTW 咨询能力准备及潜在战队机会。'),['Explore team learning','探索团队学习'])
    fll+=section(f'''<div class="split"><div><h2>{t('Build skills.<br>Learn as a team.','积累技能，<br>学习团队协作。')}</h2><ul class="check-list"><li>{t('Explore a problem and develop ideas together.','共同探索问题，发展解决思路。')}</li><li>{t('Build, code and test a robot through repeated attempts.','通过反复尝试搭建、编程和测试机器人。')}</li><li>{t('Explain decisions and listen to other perspectives.','解释自己的决策，倾听不同观点。')}</li></ul></div><div class="card"><span class="status">{t('TTW team availability not yet confirmed','TTW 战队开放情况尚未确认')}</span><h3>{t('Interested in a team?','对战队感兴趣？')}</h3><p>{t('A consultation will clarify experience, grade, family time commitment and any future group options. Team registration, event entry and fees are not currently offered through this website.','咨询将帮助明确经验、年级、家庭时间投入及未来班组选择。本网站目前不提供战队注册、赛事报名或收费。')}</p>{button(t('Ask about FIRST LEGO League','咨询 FIRST LEGO League'),'book-a-trial.html?program=fll')}</div></div><div class="callout">{t('Season formats and regional availability can change. TTW will need to confirm the current format, local eligibility and coaching capacity before offering a team place.','赛季形式和地区安排可能变化。TTW 需确认当前形式、本地参赛资格及教练安排后，才能提供战队席位。')} <a href="https://www.firstinspires.org/programs/fll/">{t('Check the official FIRST program information →','查看 FIRST 官方项目信息 →')}</a></div><p class="small">{t('Official overview checked September 17, 2026. FIRST and LEGO are trademarks of their respective owners; this page does not claim TTW affiliation, endorsement or team registration.','官方概览核对日期：2026 年 9 月 17 日。FIRST 和 LEGO 为各自权利人的商标；本页不表示 TTW 已获其认可、授权或完成战队注册。')}</p>''','tinted')+cta()
    render('first-lego-league.html','FIRST LEGO League',t('Explore FIRST LEGO League interests at TTW. Ask about preparation and possible team opportunities; availability must be confirmed.','了解 TTW 的 FIRST LEGO League 咨询方向。咨询能力准备及潜在战队机会，具体安排需确认。'),fll,'fll')
    camps=heading(t('School breaks.<br>Fresh discoveries.','学校假期，<br>探索新发现。'),t('Interested in a hands-on break from the usual routine? Tell us which school holiday works for your family.','希望假期里有不一样的动手体验？告诉我们适合您家庭的学校假期。'),['Camps · Future dates','营地 · 排期待定'])
    camps+=section('<div class="grid three">'+''.join(f'<article class="card"><h3>{t(e,z)}</h3><p>{t(d,zd)}</p><span class="status">{t("Dates & fees to be confirmed","日期与费用待确认")}</span></article>' for e,z,d,zd in [('Summer discovery','暑期探索','Project ideas that connect robotics, design and making.','将机器人、设计与创作联系起来的项目创意。'),('School-break making','学校假期创作','Explore interest in winter and March Break activities.','了解寒假及春假活动意向。'),('PA Day possibilities','PA Day 活动','A chance to try a focused hands-on challenge.','尝试专注的动手挑战。')])+'</div><div class="callout">'+t('Camp registration is not open. Dates, age groups, hours, location, supervision, fees and policies must be confirmed before any booking.','营地报名尚未开放。任何预约前，需确认日期、年龄、时间、地点、指导安排、费用及政策。')+'</div>'+button(t('Ask about future camps','咨询未来营地'),'book-a-trial.html?program=camps'),'tinted')+cta()
    render('camps.html',t('Camps','营地'),t('Register interest in future TTW STEM camps in Markham. School-break dates, fees and availability are to be confirmed.','登记 TTW 万锦未来 STEM 营地意向。学校假期日期、费用及开班情况待确认。'),camps,'camps')
